<|
.alter table silverCommDataSite policy mirroring @'{"IsEnabled": false}';
.delete table silverCommDataSite records
  <|
    let truedGridOems = dynamic(["enphase"]);
    let oemInterval = oemMetadata | project oem, _ri = reportingIntervalMinutes;
    let s = toscalar(loadSilverCommDataSiteBackfill | summarize min(sourceTimestamp));
    let e = toscalar(loadSilverCommDataSiteBackfill | summarize max(sourceTimestamp));
    // Round-to-nearest bin pairs a native with its forward-snapped trued twin (floor would miss the pair).
    // Native-wins: a native with real energy wins; only a native dropout (0) yields to its trued twin (test e6).
    let base =
        silverCommDataSite
        | where set_has_element(truedGridOems, oem)
        | where sourceTimestamp between (s .. e)
        | where siteId in ((loadSilverCommDataSiteBackfill | summarize by siteId))
        | lookup kind=leftouter oemInterval on oem
        | extend _riv = coalesce(_ri, 15)
        | extend rbin = bin(sourceTimestamp + (_riv * 1m) / 2, _riv * 1m)
        | extend isTrued = (sourceTimestamp == bin(sourceTimestamp, _riv * 1m));
    let binsel =
        base
        | summarize e_native = sumif(battery_200_IncWhExp, not(isTrued)), e_trued = sumif(battery_200_IncWhExp, isTrued),
                    n_native = countif(not(isTrued)), n_trued = countif(isTrued)
          by siteId, assetId, oem, rbin
        | extend has_both = (n_native > 0 and n_trued > 0), native_wins = (e_native > 0);
    base
    | lookup kind=leftouter binsel on siteId, assetId, oem, rbin
    | where has_both and ((native_wins and isTrued) or (not(native_wins) and not(isTrued)))
    | project-away _ri, _riv, rbin, isTrued, e_native, e_trued, n_native, n_trued, has_both, native_wins;
// Mirroring stays OFF (ADR-0007).
.delete materialized-view goldCommDataSite records
  <|
    let truedGridOems = dynamic(["enphase"]);
    let s = toscalar(loadSilverCommDataSiteBackfill | summarize min(sourceTimestamp));
    let e = toscalar(loadSilverCommDataSiteBackfill | summarize max(sourceTimestamp));
    goldCommDataSite
    | where set_has_element(truedGridOems, oem)
    | where sourceTimestamp between (s .. e)
    | where siteId in ((loadSilverCommDataSiteBackfill | summarize by siteId))
    | join kind=leftanti hint.strategy=broadcast (
        silverCommDataSite
        | where set_has_element(truedGridOems, oem)
        | where sourceTimestamp between (s .. e)
        | where siteId in ((loadSilverCommDataSiteBackfill | summarize by siteId))
        | project siteId, assetId, sourceTimestamp
      ) on siteId, assetId, sourceTimestamp;

