.set-or-append silverCommDataDevice <| loadSilverCommDataDeviceBackfill;
// Stays OFF (ADR-0007).
.alter table silverCommDataDevice policy mirroring @'{"IsEnabled": false}';
// Delete pre-existing rows by per-key ingestion_time() cutoff; site+window prune keeps the scan bounded.
.delete table silverCommDataDevice records
  <|
    let loadKeys = loadSilverCommDataDeviceBackfill | project siteId, deviceId, sourceTimestamp, measurementType;
    let targetSites = loadSilverCommDataDeviceBackfill | summarize by siteId;
    let global_min = toscalar(loadSilverCommDataDeviceBackfill | summarize min(sourceTimestamp));
    let global_max = toscalar(loadSilverCommDataDeviceBackfill | summarize max(sourceTimestamp));
    let silverWin =
        silverCommDataDevice
        | where sourceTimestamp between (global_min .. global_max)
        | where siteId in (targetSites)
        | extend _it = ingestion_time();
    let appendCut =
        silverWin
        | join kind=inner hint.strategy=broadcast loadKeys on siteId, deviceId, sourceTimestamp, measurementType
        | summarize batch_ingest = max(_it) by siteId, deviceId, sourceTimestamp, measurementType;
    silverWin
    | join kind=inner hint.strategy=broadcast appendCut on siteId, deviceId, sourceTimestamp, measurementType
    | where _it < batch_ingest;

